class Logger {
  static #instance;
  #logs = [];

  static getInstance() {
    if (!Logger.#instance) {
      Logger.#instance = new Logger();
    }
    return Logger.#instance;
  }

  log(message) {
    this.#logs.push(message);
  }
}

const a = Logger.getInstance();
const b = Logger.getInstance();
console.log(a === b); // true — نفس النسخة بالضبط

class PizzaBuilder {
  #pizza = { size: "medium", toppings: [] };
  setSize(size) { this.#pizza.size = size; return this; }
  addTopping(t) { this.#pizza.toppings.push(t); return this; }
  build() { return this.#pizza; }
}

const pizza = new PizzaBuilder().setSize("large").addTopping("جبنة").build();
console.log(pizza); // { size: 'large', toppings: ['جبنة'] }

class CreditCardStrategy { pay(amount) { console.log(`دفع ${amount} ببطاقة`); } }
class PayPalStrategy { pay(amount) { console.log(`دفع ${amount} عبر PayPal`); } }

class Cart {
  constructor(strategy) { this.strategy = strategy; }
  checkout(amount) { this.strategy.pay(amount); }
}

const cart = new Cart(new PayPalStrategy());
cart.checkout(50); // دفع 50 عبر PayPal

