class Editor {
  content = "";
  save() { return { content: this.content }; } // Memento
  restore(m) { this.content = m.content; }
}

class History {
  #snapshots = [];
  backup(editor) { this.#snapshots.push(editor.save()); }
  undo(editor) { const s = this.#snapshots.pop(); if (s) editor.restore(s); }
}

const editor = new Editor();
const history = new History();
history.backup(editor);
editor.content = "مرحبا";
history.undo(editor);
console.log(editor.content); // ""

class ChatRoom {
  #users = [];
  register(user) { user.room = this; this.#users.push(user); }
  send(text, from) {
    this.#users.forEach((u) => u !== from && u.receive(text, from));
  }
}

class User {
  constructor(name) { this.name = name; }
  send(text) { this.room.send(text, this); }
  receive(text, from) { console.log(`${from.name} → ${this.name}: ${text}`); }
}

const room = new ChatRoom();
const sara = new User("سارة"), omar = new User("عمر");
room.register(sara); room.register(omar);
sara.send("أهلاً!"); // سارة → عمر: أهلاً!
